import { Color, DirectionalLight, BoxGeometry, PlaneGeometry, Mesh, Group, Texture } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mix, smoothstep, texture, color, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = (config.intent?.visualSpec?.colors) ?? config.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Journal 1', role: 'headline', typography: { fontSize: 39 } },
    ];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const headlineText = (headlineItem?.text ?? 'Journal 1').replace(/[^\x00-\x7F]/g, '');
  const headlineSize = headlineItem?.typography?.fontSize ?? 39;

  const root = new Group();
  root.name = 'journal-card-1-label';

  // inner group carries entrance/settle motion, root transform is owned by the adapter
  const inner = new Group();
  root.add(inner);

  // ---- dims ----
  const cardW = 1.7;
  const cardH = 0.55;
  const cardD = 0.05;

  // ---- back panel (depth plane 1: subtle backdrop behind the label) ----
  const backGeo = new PlaneGeometry(cardW * 1.06, cardH * 1.12);
  const backMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.0,
  });
  backMat.colorNode = color(colors.surface);
  const backPanel = new Mesh(backGeo, backMat);
  backPanel.position.set(0, 0, -0.03);
  inner.add(backPanel);

  // ---- brushed metal label plate (depth plane 2: the subject) ----
  const brushedTexHolder = new Texture();
  brushedTexHolder.needsUpdate = true;

  const plateGeo = new BoxGeometry(cardW, cardH, cardD);
  const plateMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
  });

  const uvNode = uv();
  const gradient = mix(color(colors.surface), color(colors.ink), smoothstep(0.0, 1.0, uvNode.y));
  const mapSample = texture(brushedTexHolder, uvNode.mul(vec2(2.0, 1.0)));
  const noiseSeed = fract(sin(dot(uvNode, vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = noiseSeed.mul(0.05).sub(0.025);
  const blended = mix(gradient, mapSample.rgb, 0.55);
  plateMat.colorNode = blended.add(grain);

  const plate = new Mesh(plateGeo, plateMat);
  inner.add(plate);

  ctx.textureLoader
    .loadTexture(config.imageUrl ?? '/prism-assets/chrome/brushed-metal.map.png')
    .then((tex) => {
      brushedTexHolder.image = tex.image;
      brushedTexHolder.wrapS = tex.wrapS;
      brushedTexHolder.wrapT = tex.wrapT;
      brushedTexHolder.needsUpdate = true;
    })
    .catch(() => {});

  // ---- accent underline (depth plane 3: foreground accent, <=10% of frame) ----
  const accentGeo = new PlaneGeometry(0.42, 0.018);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = color(colors.accent);
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.set(-0.42, -0.14, cardD * 0.5 + 0.004);
  inner.add(accentLine);

  // ---- headline text: "Journal 1" — the single brightest element ----
  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: headlineSize,
    color: colors.paper,
    align: 'left',
  });
  headline.position.set(-0.72, 0.02, cardD * 0.5 + 0.006);
  inner.add(headline);

  // ---- node-local rim light (accent-tinted, within intensity cap) ----
  const rim = new DirectionalLight(new Color(colors.accent), 0.55);
  rim.position.set(-1.2, 0.6, 1.4);
  inner.add(rim);
  inner.add(rim.target);

  // ---- entrance / weighted-settle motion ----
  inner.position.set(0, 0.3, 0);
  inner.scale.set(0.96, 0.96, 0.96);

  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(inner.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0.05);

  // ---- primitives (spec ships none for this node, loop defensively) ----
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    if (prim?.name && ctx.primitives?.[prim.name]) {
      primitiveHandles.push(ctx.primitives[prim.name](root, prim.params ?? {}));
    }
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
    }
    backGeo.dispose();
    backMat.dispose();
    plateGeo.dispose();
    plateMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    brushedTexHolder.dispose();
    rim.dispose?.();
  };

  return root;
}
